  1	package com.pousadameraalta.util;
  2	
  3	import com.pousadameraalta.model.Reservation;
  4	
  5	public class DocumentGenerator {
  6	
  7	    public static String generateReceipt(Reservation reservation) {
  8	        StringBuilder sb = new StringBuilder();
  9	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
 10	        sb.append("Hóspede: ").append(reservation.getGuestName()).append(" (CPF ")
 11	          .append(Formatter.formatCpf(reservation.getGuestCpf())).append(")\n");
 12	        sb.append("Quarto: ").append(reservation.getRoomNumber()).append(" (").append(getQuartType(reservation.getRoomNumber())).append(")\n");
 13	        sb.append("Entrada: ").append(Formatter.formatPtDate(reservation.getCheckIn()))
 14	          .append(" | Saída: ").append(Formatter.formatPtDate(reservation.getCheckOut()))
 15	          .append(" | ").append(getNightsText(reservation.getNights(), true)).append("\n");
 16	        sb.append("Diárias: ").append(Formatter.formatBrl(reservation.getSubtotal())).append("\n");
 17	
 18	        if (reservation.getDiscount().signum() > 0) {
 19	            sb.append("Desconto: ").append(Formatter.formatBrl(reservation.getDiscount())).append("\n");
 20	        }
 21	
 22	        sb.append("Total: ").append(Formatter.formatBrl(reservation.getTotal())).append("\n");
 23	
 24	        return sb.toString();
 25	    }
 26	
 27	    public static String generateInvoice(Reservation reservation) {
 28	        StringBuilder sb = new StringBuilder();
 29	        sb.append("Fatura de hospedagem nº ").append(reservation.getId()).append("\n");
 30	        sb.append("Empresa: ").append(reservation.getCompanyName()).append(" (CNPJ ")
 31	          .append(Formatter.formatCnpj(reservation.getCompanyCnpj())).append(")\n");
 32	        sb.append("Hóspede: ").append(reservation.getGuestName()).append("\n");
 33	        sb.append("Quarto: ").append(reservation.getRoomNumber()).append(" (").append(getQuartType(reservation.getRoomNumber())).append(")\n");
 34	        sb.append("Entrada: ").append(Formatter.formatPtDate(reservation.getCheckIn()))
 35	          .append(" | Saída: ").append(Formatter.formatPtDate(reservation.getCheckOut()))
 36	          .append(" | ").append(getNightsText(reservation.getNights(), true)).append("\n");
 37	        sb.append("Diárias: ").append(Formatter.formatBrl(reservation.getSubtotal())).append("\n");
 38	
 39	        if (reservation.getDiscount().signum() > 0) {
 40	            sb.append("Desconto: ").append(Formatter.formatBrl(reservation.getDiscount())).append("\n");
 41	        }
 42	
 43	        sb.append("Total: ").append(Formatter.formatBrl(reservation.getTotal())).append("\n");
 44	
 45	        var iss = PriceCalculator.calculateIss(reservation.getTotal());
 46	        sb.append("ISS retido (5%): ").append(Formatter.formatBrl(iss)).append("\n");
 47	
 48	        return sb.toString();
 49	    }
 50	
 51	    public static String generateBookingReceipt(Reservation reservation) {
 52	        StringBuilder sb = new StringBuilder();
 53	        sb.append("Booking receipt no. ").append(reservation.getId()).append("\n");
 54	        sb.append("Guest: ").append(reservation.getGuestName()).append(" (passport ")
 55	          .append(reservation.getGuestPassport()).append(", ").append(reservation.getGuestCountry()).append(")\n");
 56	        sb.append("Room: ").append(reservation.getRoomNumber()).append(" (").append(getQuartType(reservation.getRoomNumber())).append(")\n");
 57	        sb.append("Check-in: ").append(Formatter.formatEnDate(reservation.getCheckIn()))
 58	          .append(" | Check-out: ").append(Formatter.formatEnDate(reservation.getCheckOut()))
 59	          .append(" | ").append(getNightsText(reservation.getNights(), false)).append("\n");
 60	        sb.append("Nights: ").append(Formatter.formatBrlEnglish(reservation.getSubtotal())).append("\n");
 61	
 62	        if (reservation.getDiscount().signum() > 0) {
 63	            sb.append("Discount: ").append(Formatter.formatBrlEnglish(reservation.getDiscount())).append("\n");
 64	        }
 65	
 66	        sb.append("Total: ").append(Formatter.formatBrlEnglish(reservation.getTotal())).append("\n");
 67	
 68	        return sb.toString();
 69	    }
 70	
 71	    private static String getQuartType(int roomNumber) {
 72	        return switch (roomNumber) {
 73	            case 101, 102 -> "STANDARD";
 74	            case 201, 202 -> "DELUXE";
 75	            case 301 -> "SUITE";
 76	            default -> "UNKNOWN";
 77	        };
 78	    }
 79	
 80	    private static String getNightsText(int nights, boolean portuguese) {
 81	        if (portuguese) {
 82	            return nights == 1 ? "1 diária" : nights + " diárias";
 83	        } else {
 84	            return nights == 1 ? "1 night" : nights + " nights";
 85	        }
 86	    }
 87	}
 88	package com.pousadameraalta.service;
 89	
 90	import com.pousadameraalta.model.*;
 91	import com.pousadameraalta.repository.DataStore;
 92	import com.pousadameraalta.util.PriceCalculator;
 93	import com.pousadameraalta.util.DocumentGenerator;
 94	import com.pousadameraalta.util.Formatter;
 95	
 96	import java.math.BigDecimal;
 97	import java.time.LocalDate;
 98	
 99	public class ReservationService {
100	    private final DataStore dataStore = DataStore.getInstance();
101	
102	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
103	                                         String guestCpf, String companyCnpj, String companyName,
104	                                         String guestPassport, String guestCountry,
105	                                         LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan)
106	            throws Exception {
107	
108	        Room room = dataStore.getRoom(roomNumber);
109	        if (room == null) {
110	            throw new Exception("ROOM_NOT_FOUND");
111	        }
112	
113	        if (guests < 1 || guests > room.getCapacity()) {
114	            throw new Exception(guests > room.getCapacity() ? "CAPACITY_EXCEEDED" : "INVALID_REQUEST");
115	        }
116	
117	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
118	            throw new Exception("INVALID_REQUEST");
119	        }
120	
121	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
122	            throw new Exception("ROOM_UNAVAILABLE");
123	        }
124	
125	        int nights = PriceCalculator.calculateNights(checkIn, checkOut);
126	
127	        BigDecimal nightPrice = PriceCalculator.calculateNightPrice(room.getNightlyRate(), checkIn);
128	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(nightPrice, nights);
129	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan == RatePlan.NON_REFUNDABLE);
130	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
131	
132	        Reservation reservation = new Reservation(
133	                dataStore.getNextReservationId(),
134	                roomNumber,
135	                guestName,
136	                guestEmail,
137	                guestCpf,
138	                companyCnpj,
139	                companyName,
140	                guestPassport,
141	                guestCountry,
142	                checkIn,
143	                checkOut,
144	                guests,
145	                ratePlan,
146	                nights,
147	                subtotal,
148	                discount,
149	                total
150	        );
151	
152	        return dataStore.createReservation(reservation);
153	    }
154	
155	    public Reservation confirmReservation(long id) throws Exception {
156	        Reservation reservation = dataStore.getReservation(id);
157	        if (reservation == null) {
158	            throw new Exception("RESERVATION_NOT_FOUND");
159	        }
160	
161	        if (reservation.getStatus() != ReservationStatus.PENDING) {
162	            throw new Exception("OPERATION_NOT_ALLOWED");
163	        }
164	
165	        reservation.setStatus(ReservationStatus.CONFIRMED);
166	        reservation.setAmountPaid(reservation.getTotal());
167	
168	        String document = getDocument(reservation);
169	        String emailBody = generateConfirmationEmail(reservation, document);
170	
171	        dataStore.saveMessage("EMAIL", reservation.getGuestEmail(), "Reserva confirmada - Pousada Maré Alta", emailBody);
172	
173	        return dataStore.saveReservation(reservation);
174	    }
175	
176	    public Reservation cancelReservation(long id) throws Exception {
177	        Reservation reservation = dataStore.getReservation(id);
178	        if (reservation == null) {
179	            throw new Exception("RESERVATION_NOT_FOUND");
180	        }
181	
182	        ReservationStatus status = reservation.getStatus();
183	        if (status == ReservationStatus.CHECKED_IN || status == ReservationStatus.CHECKED_OUT || status == ReservationStatus.CANCELLED) {
184	            throw new Exception("OPERATION_NOT_ALLOWED");
185	        }
186	
187	        BigDecimal refundAmount = BigDecimal.ZERO;
188	        if (status == ReservationStatus.CONFIRMED && reservation.getRatePlan() == RatePlan.STANDARD) {
189	            refundAmount = reservation.getAmountPaid();
190	        }
191	
192	        reservation.setStatus(ReservationStatus.CANCELLED);
193	        reservation.setRefund(refundAmount);
194	
195	        return dataStore.saveReservation(reservation);
196	    }
197	
198	    public Reservation checkIn(long id) throws Exception {
199	        Reservation reservation = dataStore.getReservation(id);
200	        if (reservation == null) {
201	            throw new Exception("RESERVATION_NOT_FOUND");
202	        }
203	
204	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
205	            throw new Exception("OPERATION_NOT_ALLOWED");
206	        }
207	
208	        reservation.setStatus(ReservationStatus.CHECKED_IN);
209	        return dataStore.saveReservation(reservation);
210	    }
211	
212	    public Reservation checkOut(long id) throws Exception {
213	        Reservation reservation = dataStore.getReservation(id);
214	        if (reservation == null) {
215	            throw new Exception("RESERVATION_NOT_FOUND");
216	        }
217	
218	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
219	            throw new Exception("OPERATION_NOT_ALLOWED");
220	        }
221	
222	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
223	        return dataStore.saveReservation(reservation);
224	    }
225	
226	    public Reservation getReservation(long id) throws Exception {
227	        Reservation reservation = dataStore.getReservation(id);
228	        if (reservation == null) {
229	            throw new Exception("RESERVATION_NOT_FOUND");
230	        }
231	        return reservation;
232	    }
233	
234	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
235	        return dataStore.getAllReservations().stream()
236	                .filter(r -> r.getRoomNumber() == roomNumber && r.getStatus() != ReservationStatus.CANCELLED)
237	                .anyMatch(r -> {
238	                    LocalDate rCheckOut = r.getCheckOut();
239	                    LocalDate rCheckIn = r.getCheckIn();
240	                    return !(checkOut.isBefore(rCheckIn) || checkIn.isAfter(rCheckOut) || checkIn.isEqual(rCheckOut));
241	                });
242	    }
243	
244	    private String getDocument(Reservation reservation) {
245	        if (reservation.getGuestCpf() != null) {
246	            return DocumentGenerator.generateReceipt(reservation);
247	        } else if (reservation.getCompanyCnpj() != null) {
248	            return DocumentGenerator.generateInvoice(reservation);
249	        } else {
250	            return DocumentGenerator.generateBookingReceipt(reservation);
251	        }
252	    }
253	
254	    private String generateConfirmationEmail(Reservation reservation, String document) {
255	        StringBuilder sb = new StringBuilder();
256	        sb.append("Olá, ").append(reservation.getGuestName()).append("!\n\n");
257	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
258	        sb.append(document).append("\n");
259	        sb.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
260	        sb.append("Até breve!\n");
261	        return sb.toString();
262	    }
263	}
