183	        if (status == ReservationStatus.CHECKED_IN || status == ReservationStatus.CHECKED_OUT || status == ReservationStatus.CANCELLED) {
184	            throw new Exception("OPERATION_NOT_ALLOWED");
185	        }
186	
187	        BigDecimal refundAmount = BigDecimal.ZERO;
188	        if (status == ReservationStatus.CONFIRMED && reservation.getRatePlan() == RatePlan.STANDARD) {
189	            refundAmount = reservation.getAmountPaid();
190	        }
191	
192	        reservation.setStatus(ReservationStatus.CANCELLED);
193	        reservation.setRefund(refundAmount);
194	
195	        return dataStore.saveReservation(reservation);
196	    }
197	
198	    public Reservation checkIn(long id) throws Exception {
199	        Reservation reservation = dataStore.getReservation(id);
200	        if (reservation == null) {
201	            throw new Exception("RESERVATION_NOT_FOUND");
202	        }
203	
204	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
205	            throw new Exception("OPERATION_NOT_ALLOWED");
206	        }
207	
208	        reservation.setStatus(ReservationStatus.CHECKED_IN);
209	        return dataStore.saveReservation(reservation);
210	    }
211	
212	    public Reservation checkOut(long id) throws Exception {
213	        Reservation reservation = dataStore.getReservation(id);
214	        if (reservation == null) {
215	            throw new Exception("RESERVATION_NOT_FOUND");
216	        }
217	
218	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
219	            throw new Exception("OPERATION_NOT_ALLOWED");
220	        }
221	
222	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
223	        return dataStore.saveReservation(reservation);
224	    }
225	
226	    public Reservation getReservation(long id) throws Exception {
227	        Reservation reservation = dataStore.getReservation(id);
228	        if (reservation == null) {
229	            throw new Exception("RESERVATION_NOT_FOUND");
230	        }
231	        return reservation;
232	    }
233	
234	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
235	        return dataStore.getAllReservations().stream()
236	                .filter(r -> r.getRoomNumber() == roomNumber && r.getStatus() != ReservationStatus.CANCELLED)
237	                .anyMatch(r -> {
238	                    LocalDate rCheckOut = r.getCheckOut();
239	                    LocalDate rCheckIn = r.getCheckIn();
240	                    return !(checkOut.isBefore(rCheckIn) || checkIn.isAfter(rCheckOut) || checkIn.isEqual(rCheckOut));
241	                });
242	    }
243	
244	    private String getDocument(Reservation reservation) {
245	        if (reservation.getGuestCpf() != null) {
246	            return DocumentGenerator.generateReceipt(reservation);
247	        } else if (reservation.getCompanyCnpj() != null) {
248	            return DocumentGenerator.generateInvoice(reservation);
249	        } else {
250	            return DocumentGenerator.generateBookingReceipt(reservation);
251	        }
252	    }
253	
254	    private String generateConfirmationEmail(Reservation reservation, String document) {
255	        StringBuilder sb = new StringBuilder();
256	        sb.append("Olá, ").append(reservation.getGuestName()).append("!\n\n");
257	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
258	        sb.append(document).append("\n");
259	        sb.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
260	        sb.append("Até breve!\n");
261	        return sb.toString();
262	    }
263	}
