 11	import io.javalin.http.Context;
 12	
 13	import java.time.LocalDate;
 14	import java.util.stream.Collectors;
 15	
 16	public class ApiHandler {
 17	    private final Gson gson = new Gson();
 18	    private final ReservationService reservationService = new ReservationService();
 19	    private final ReportService reportService = new ReportService();
 20	    private final DataStore dataStore = DataStore.getInstance();
 21	
 22	    public void getRooms(Context ctx) {
 23	        var rooms = dataStore.getAllRooms().stream()
 24	                .map(RoomResponse::new)
 25	                .collect(Collectors.toList());
 26	        ctx.json(rooms);
