 28	
 29	    public void createReservation(Context ctx) {
 30	        try {
 31	            ReservationRequest req = gson.fromJson(ctx.body(), ReservationRequest.class);
 32	
 33	            RequestValidator.validateCreateReservation(req);
 34	
 35	            LocalDate checkIn = LocalDate.parse(req.checkIn);
 36	            LocalDate checkOut = LocalDate.parse(req.checkOut);
 37	
 38	            Reservation reservation = reservationService.createReservation(
 39	                    req.roomNumber,
 40	                    req.guestName,
 41	                    req.guestEmail,
 42	                    req.guestCpf,
 43	                    req.companyCnpj,
 44	                    req.companyName,
 45	                    req.guestPassport,
 46	                    req.guestCountry,
 47	                    checkIn,
 48	                    checkOut,
 49	                    req.guests,
 50	                    RatePlan.valueOf(req.ratePlan)
 51	            );
 52	
 53	            ctx.status(201);
 54	            ctx.json(ReservationResponse.fromModel(reservation, req.checkIn, req.checkOut));
 55	        } catch (RequestValidator.ValidationException e) {
 56	            ctx.status(400);
