145	    public void getDocument(Context ctx) {
146	        try {
147	            long id = Long.parseLong(ctx.pathParam("id"));
148	            Reservation reservation = reservationService.getReservation(id);
149	
150	            if (reservation.getAmountPaid().signum() == 0) {
151	                ctx.status(404);
152	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Document not available for unpaid reservations"));
153	                return;
154	            }
155	
156	            ctx.json(DocumentResponse.fromReservation(reservation));
