172	    public void getOccupancyReport(Context ctx) {
173	        try {
174	            String date = ctx.queryParam("date");
175	            if (date == null || date.trim().isEmpty()) {
176	                ctx.status(400);
177	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Date parameter is required"));
178	                return;
179	            }
180	
181	            RequestValidator.validateDate(date);
182	            LocalDate localDate = LocalDate.parse(date);
183	
184	            String csv = reportService.generateOccupancyReport(localDate);
185	            ctx.contentType("text/csv;charset=utf-8");
186	            ctx.result(csv);
187	        } catch (RequestValidator.ValidationException e) {
188	            ctx.status(400);
189	            ctx.json(new ErrorResponse(e.errorCode, e.errorMessage));
190	        }
191	    }
192	
193	    public void getRevenueReport(Context ctx) {
194	        try {
195	            String month = ctx.queryParam("month");
196	            if (month == null || month.trim().isEmpty()) {
197	                ctx.status(400);
198	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Month parameter is required"));
199	                return;
200	            }
201	
202	            RequestValidator.validateMonth(month);
203	            String csv = reportService.generateRevenueReport(month);
204	            ctx.contentType("text/csv;charset=utf-8");
205	            ctx.result(csv);
206	        } catch (RequestValidator.ValidationException e) {
207	            ctx.status(400);
208	            ctx.json(new ErrorResponse(e.errorCode, e.errorMessage));
209	        } catch (Exception e) {
210	            handleServiceException(ctx, e);
211	        }
212	    }
213	
214	    private void handleServiceException(Context ctx, Exception e) {
215	        String message = e.getMessage();
216	
217	        if ("ROOM_NOT_FOUND".equals(message)) {
218	            ctx.status(404);
219	            ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
220	        } else if ("RESERVATION_NOT_FOUND".equals(message)) {
221	            ctx.status(404);
222	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
223	        } else if ("ROOM_UNAVAILABLE".equals(message)) {
224	            ctx.status(409);
225	            ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for these dates"));
226	        } else if ("CAPACITY_EXCEEDED".equals(message)) {
227	            ctx.status(422);
228	            ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Guests exceed room capacity"));
229	        } else if ("OPERATION_NOT_ALLOWED".equals(message)) {
230	            ctx.status(409);
231	            ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for current reservation status"));
232	        } else if ("INVALID_REQUEST".equals(message)) {
233	            ctx.status(400);
234	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
235	        } else {
236	            ctx.status(500);
237	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "An internal error occurred"));
238	        }
239	    }
240	}
241	package com.pousadameraalta.api.validation;
242	
243	import com.pousadameraalta.api.dto.ReservationRequest;
244	import java.time.LocalDate;
245	import java.time.format.DateTimeParseException;
246	
247	public class RequestValidator {
248	
249	    public static void validateCreateReservation(ReservationRequest req) throws ValidationException {
250	        if (req.roomNumber == 0) {
251	            throw new ValidationException("INVALID_REQUEST", "Room number is required");
252	        }
253	        if (req.guestName == null || req.guestName.trim().isEmpty()) {
254	            throw new ValidationException("INVALID_REQUEST", "Guest name is required");
255	        }
256	        if (req.guestEmail == null || req.guestEmail.trim().isEmpty()) {
257	            throw new ValidationException("INVALID_REQUEST", "Guest email is required");
258	        }
259	        if (req.checkIn == null || req.checkIn.trim().isEmpty()) {
260	            throw new ValidationException("INVALID_REQUEST", "Check-in date is required");
261	        }
262	        if (req.checkOut == null || req.checkOut.trim().isEmpty()) {
263	            throw new ValidationException("INVALID_REQUEST", "Check-out date is required");
264	        }
265	        if (req.guests == 0) {
266	            throw new ValidationException("INVALID_REQUEST", "Guests count is required");
267	        }
268	        if (req.ratePlan == null || req.ratePlan.trim().isEmpty()) {
269	            throw new ValidationException("INVALID_REQUEST", "Rate plan is required");
270	        }
271	
272	        try {
273	            LocalDate.parse(req.checkIn);
274	            LocalDate.parse(req.checkOut);
275	        } catch (DateTimeParseException e) {
276	            throw new ValidationException("INVALID_REQUEST", "Invalid date format");
277	        }
278	
279	        int identificationCount = 0;
280	        if (req.guestCpf != null && !req.guestCpf.trim().isEmpty()) identificationCount++;
281	        if (req.companyCnpj != null && !req.companyCnpj.trim().isEmpty()) identificationCount++;
282	        if (req.guestPassport != null && !req.guestPassport.trim().isEmpty()) identificationCount++;
283	
284	        if (identificationCount != 1) {
285	            throw new ValidationException("INVALID_REQUEST", "Exactly one identification method is required");
286	        }
287	
288	        if (req.companyCnpj != null && (req.companyName == null || req.companyName.trim().isEmpty())) {
289	            throw new ValidationException("INVALID_REQUEST", "Company name is required when CNPJ is provided");
290	        }
291	
292	        if (req.guestPassport != null && (req.guestCountry == null || req.guestCountry.trim().isEmpty())) {
293	            throw new ValidationException("INVALID_REQUEST", "Country is required when passport is provided");
294	        }
295	
296	        if (req.guests < 1) {
297	            throw new ValidationException("INVALID_REQUEST", "Guests count must be at least 1");
298	        }
299	    }
300	
301	    public static void validateDate(String dateStr) throws ValidationException {
302	        try {
303	            LocalDate.parse(dateStr);
304	        } catch (DateTimeParseException e) {
305	            throw new ValidationException("INVALID_REQUEST", "Invalid date format");
306	        }
307	    }
308	
309	    public static void validateMonth(String monthStr) throws ValidationException {
310	        try {
311	            String[] parts = monthStr.split("-");
312	            if (parts.length != 2) throw new NumberFormatException();
313	            int year = Integer.parseInt(parts[0]);
314	            int month = Integer.parseInt(parts[1]);
315	            if (month < 1 || month > 12) throw new NumberFormatException();
316	        } catch (Exception e) {
317	            throw new ValidationException("INVALID_REQUEST", "Invalid month format");
318	        }
319	    }
320	
321	    public static class ValidationException extends Exception {
322	        public final String errorCode;
323	        public final String errorMessage;
324	
325	        public ValidationException(String errorCode, String errorMessage) {
326	            super(errorMessage);
327	            this.errorCode = errorCode;
328	            this.errorMessage = errorMessage;
329	        }
330	    }
331	}
