334	import com.pousadameraalta.model.Reservation;
335	import com.pousadameraalta.util.DocumentGenerator;
336	import java.math.BigDecimal;
337	
338	public class DocumentResponse {
339	    public String title;
340	    public long reservationId;
341	    public String guestName;
342	    public String guestCpf;
343	    public String companyCnpj;
344	    public String companyName;
345	    public String guestPassport;
346	    public String guestCountry;
347	    public int roomNumber;
348	    public String roomType;
349	    public String checkIn;
350	    public String checkOut;
351	    public int nights;
352	    public BigDecimal subtotal;
353	    public BigDecimal discount;
354	    public BigDecimal total;
355	    public String text;
356	
357	    public static DocumentResponse fromReservation(Reservation r) {
358	        DocumentResponse resp = new DocumentResponse();
359	        resp.title = "Comprovante de reserva";
360	        resp.reservationId = r.getId();
361	        resp.guestName = r.getGuestName();
362	        resp.guestCpf = r.getGuestCpf();
363	        resp.companyCnpj = r.getCompanyCnpj();
364	        resp.companyName = r.getCompanyName();
365	        resp.guestPassport = r.getGuestPassport();
366	        resp.guestCountry = r.getGuestCountry();
367	        resp.roomNumber = r.getRoomNumber();
368	        resp.roomType = getQuartType(r.getRoomNumber());
369	        resp.checkIn = r.getCheckIn().toString();
370	        resp.checkOut = r.getCheckOut().toString();
371	        resp.nights = r.getNights();
372	        resp.subtotal = r.getSubtotal();
373	        resp.discount = r.getDiscount();
374	        resp.total = r.getTotal();
375	
376	        if (r.getGuestCpf() != null) {
377	            resp.text = DocumentGenerator.generateReceipt(r);
378	        } else if (r.getCompanyCnpj() != null) {
379	            resp.text = DocumentGenerator.generateInvoice(r);
380	        } else {
381	            resp.text = DocumentGenerator.generateBookingReceipt(r);
382	        }
383	
384	        return resp;
385	    }
386	
387	    private static String getQuartType(int roomNumber) {
388	        return switch (roomNumber) {
389	            case 101, 102 -> "STANDARD";
390	            case 201, 202 -> "DELUXE";
391	            case 301 -> "SUITE";
392	            default -> "UNKNOWN";
393	        };
394	    }
395	}
