    17	    public String generateOccupancyReport(LocalDate date) {
    18	        StringBuilder csv = new StringBuilder();
    19	        csv.append("room,type,reservation,check_in,check_out\n");
    20	
    21	        List<Reservation> occupiedRooms = new ArrayList<>();
    22	
    23	        dataStore.getAllReservations().stream()
    24	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
    25	                .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
