    27	                           r.getStatus() == ReservationStatus.CHECKED_OUT)
    28	                .filter(r -> {
    29	                    LocalDate checkIn = r.getCheckIn();
    30	                    LocalDate checkOut = r.getCheckOut();
    31	                    return !date.isBefore(checkIn) && date.isBefore(checkOut);
    32	                })
    33	                .sorted(Comparator.comparingInt(Reservation::getRoomNumber))
    34	                .forEach(occupiedRooms::add);
    35	
    36	        for (Reservation r : occupiedRooms) {
    37	            csv.append(r.getRoomNumber()).append(",")
    38	               .append(getQuartType(r.getRoomNumber())).append(",")
    39	               .append(r.getId()).append(",")
    40	               .append(Formatter.formatIsoDate(r.getCheckIn())).append(",")
    41	               .append(Formatter.formatIsoDate(r.getCheckOut())).append("\n");
    42	        }
    43	
    44	        int totalRooms = dataStore.getAllRooms().size();
