    46	
    47	        return csv.toString();
    48	    }
    49	
    50	    public String generateRevenueReport(String month) throws Exception {
    51	        YearMonth yearMonth = parseYearMonth(month);
    52	
    53	        StringBuilder csv = new StringBuilder();
    54	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    55	
    56	        BigDecimal totalAmount = BigDecimal.ZERO;
    57	
    58	        List<Reservation> reservations = new ArrayList<>();
    59	
    60	        dataStore.getAllReservations().stream()
    61	                .filter(r -> r.getCheckIn().getYear() == yearMonth.year &&
    62	                           r.getCheckIn().getMonthValue() == yearMonth.month)
    63	                .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
    64	                           r.getStatus() == ReservationStatus.CHECKED_IN ||
    65	                           r.getStatus() == ReservationStatus.CHECKED_OUT ||
    66	                           r.getStatus() == ReservationStatus.CANCELLED)
    67	                .sorted(Comparator.comparing(Reservation::getCheckIn)
    68	                               .thenComparingLong(Reservation::getId))
    69	                .forEach(reservations::add);
    70	
    71	        for (Reservation r : reservations) {
    72	            BigDecimal amount = r.getAmountPaid();
    73	            if (r.getRefund() != null) {
    74	                amount = amount.subtract(r.getRefund());
    75	            }
    76	
    77	            if (amount.signum() > 0 || (r.getStatus() == ReservationStatus.CANCELLED && r.getAmountPaid().signum() > 0)) {
    78	                csv.append(r.getId()).append(",")
    79	                   .append(r.getRoomNumber()).append(",")
    80	                   .append(Formatter.formatIsoDate(r.getCheckIn())).append(",")
    81	                   .append(Formatter.formatIsoDate(r.getCheckOut())).append(",")
    82	                   .append(r.getStatus()).append(",")
    83	                   .append(Formatter.formatBrlCsv(amount)).append("\n");
    84	
    85	                totalAmount = totalAmount.add(amount);
    86	            }
    87	        }
    88	
    89	        csv.append("total,,,,").append(Formatter.formatBrlCsv(totalAmount)).append("\n");
    90	
    91	        return csv.toString();
    92	    }
