    96	            case 101, 102 -> "STANDARD";
    97	            case 201, 202 -> "DELUXE";
    98	            case 301 -> "SUITE";
    99	            default -> "UNKNOWN";
   100	        };
   101	    }
   102	
   103	    private YearMonth parseYearMonth(String month) throws Exception {
   104	        try {
   105	            String[] parts = month.split("-");
   106	            if (parts.length != 2) throw new NumberFormatException();
   107	            int year = Integer.parseInt(parts[0]);
   108	            int monthVal = Integer.parseInt(parts[1]);
   109	            if (monthVal < 1 || monthVal > 12) throw new NumberFormatException();
   110	            return new YearMonth(year, monthVal);
   111	        } catch (Exception e) {
   112	            throw new Exception("INVALID_REQUEST");
   113	        }
   114	    }
   115	
   116	    private static class YearMonth {
   117	        int year;
   118	        int month;
   119	
   120	        YearMonth(int year, int month) {
   121	            this.year = year;
   122	            this.month = month;
   123	        }
   124	    }
   125	}
