     1	package com.pousadameraalta.util;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	public class PriceCalculator {
     8	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
     9	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    10	
    11	    public static boolean isHighSeason(LocalDate date) {
    12	        int month = date.getMonthValue();
    13	        int dayOfMonth = date.getDayOfMonth();
    14	
    15	        if (month == 7) return true;
    16	        if (month == 12) return true;
    17	        if (month == 1) return true;
    18	        if (month == 2 && dayOfMonth <= 28) return true;
    19	
    20	        return false;
    21	    }
    22	
    23	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
    24	        if (isHighSeason(date)) {
    25	            return roundToEvenCents(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
    26	        }
    27	        return roundToEvenCents(baseRate);
    28	    }
    29	
    30	    public static BigDecimal calculateSubtotal(BigDecimal nightPrice, int nights) {
    31	        return roundToEvenCents(nightPrice.multiply(BigDecimal.valueOf(nights)));
    32	    }
    33	
    34	    public static BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
    35	        if (!isNonRefundable) {
    36	            return BigDecimal.ZERO;
    37	        }
    38	        return roundToEvenCents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
    39	    }
    40	
    41	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    42	        return roundToEvenCents(subtotal.subtract(discount));
    43	    }
    44	
    45	    public static BigDecimal calculateIss(BigDecimal total) {
    46	        return roundToEvenCents(total.multiply(new BigDecimal("0.05")));
    47	    }
    48	
    49	    public static BigDecimal roundToEvenCents(BigDecimal value) {
    50	        return value.setScale(2, RoundingMode.HALF_EVEN);
    51	    }
    52	
    53	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    54	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    55	    }
    56	}
